function javaClass_changed() {
	m = form.getConfig("method");
	fc = new Packages.com.ibm.di.fc.JavaClassFC();
	fc.setConfiguration(form.getConfigObject());
	form.getControl("method").setItems(fc.getMethods());
	if (m != null)
		form.getControl("method").setText(m);
}
function method_changed() {
	fc = new Packages.com.ibm.di.fc.JavaClassFC();
	try {
		fc.updateSchema(form.getConfigObject().getParent());
	} catch (e) {}
}
javaClass_changed();

function selectJarFile() {
	selectFileWithFilter("jar");
}
function selectJavaClass () {
	jarFile = form.getConfig("jarFile");
	if (jarFile == null)
			return;

	v = new java.util.Vector();

	try {
		if (jarFile.endsWith(".class")) {
			c = com.ibm.di.loader.IDILoader.getInstance().loadClassFromFile(jarFile);
			if (c!= null)
				v.add(c.getName());
		} else {
			jf = new java.util.jar.JarFile(jarFile);

			for (e = jf.entries(); e.hasMoreElements();) {
				entry = e.nextElement();
				name = entry.getName();

				if (! entry.isDirectory() && name.endsWith(".class")) {
					name = name.substring(0, name.length()-6);

					v.add(name.replace('/', '.'));
				}
			}
		}
	} catch (error) {
		form.alert(error.toString());
	}

	if (v.size() == 0)
		javaClass = null;
	else if (v.size() == 1)
		javaClass = v.get(0);
	else
		javaClass = form.chooseFromList("JC_SELECT", v);

	if ( javaClass != null ) {
		form.setConfig("javaClass", javaClass.toString() );
		form.updateControl("javaClass");
	}
}
